var JwtUtils = class {
  // IMPORTANT: doesn't validate the token
  static decode(token) {
    try {
      return (0, import_jwt_decode.default)(token);
    } catch (err) {
      Logger.error("JwtUtils.decode", err);
      throw err;
    }
  }
};
```
And how is `__toESM` implemented? Let's check `dist/umd/oidc-client-ts.js` around line 1 or grep for `__toESM`.

